$seed$::jsonb) as item(
  "sourceId" text,
  id bigint,
  date text,
  code text,
  name text,
  "criterionKey" text,
  criterion text,
  result text,
  justification text,
  observations text,
  source text
)
)
insert into public.evaluations (
  course_code,
  course_name,
  criterion_key,
  criterion_label,
  status,
  current_question,
  final_result,
  justification,
  state,
  created_by,
  created_at,
  updated_at,
  completed_at
)
select
  seed.code,
  seed.name,
  seed."criterionKey",
  seed.criterion,
  'concluida',
  null,
  seed.result,
  seed.justification,
  jsonb_build_object(
    'sourceId', seed."sourceId",
    'source', seed.source,
    'sourceDate', seed.date,
    'observations', seed.observations,
    'imported', true
  ),
  (select id from public.profiles where role = 'admin' order by created_at limit 1),
  now(),
  now(),
  now()
from seed
where not exists (
  select 1
  from public.evaluations existing
  where existing.state ->> 'sourceId' = seed."sourceId"
);

commit;

-- Conferência: o resultado esperado para a planilha atual é 77.
select count(*) as decisoes_importadas
from public.evaluations
where state ->> 'imported' = 'true';
